def is_good_triple(x, y, z):
    # Check if (x+1)^y is divisible by x^z + 1
    try:
        numerator = (x + 1)**y
        denominator = x**z + 1
        if denominator == 0:
            # Should not happen since x, z >= 1
            return False
        return numerator % denominator == 0
    except OverflowError:
        # Handle potential overflow for very large numbers, though for y < 100
        # and x <= 5, standard Python integers should be fine.
        # If overflow were a concern, we'd use modular arithmetic or prime factorization.
        # Since we are checking divisibility, we rely on Python's arbitrary precision integers.
        return False

good_triples = []
X_max = 5
Z_max = 10
Y_max = 99

for x in range(1, X_max + 1):
    for z in range(1, Z_max + 1):
        for y in range(1, Y_max + 1):
            if is_good_triple(x, y, z):
                good_triples.append((x, y, z))

# Print results in a readable format
print("Found good triples (x, y, z):")
for triple in good_triples:
    print(triple)

print(f"\nTotal number of good triples found: {len(good_triples)}")

import math

def is_power_of_three(n):
    if n <= 0:
        return False
    return (n & (n - 1) == 0 and n > 0 and n.bit_count() == 1) or (n > 0 and (n % 3 == 0 and is_power_of_three(n // 3)))

def is_power_of_three_v2(n):
    if n <= 0:
        return False
    while n % 3 == 0:
        n //= 3
    return n == 1

# Iterate x from 2 up to 100 (since x=1 gives 1 = 3^0, which is usually excluded in the k>=1 case)
solutions = []
for x in range(2, 101):
    D = x*x - x + 1
    if is_power_of_three_v2(D):
        solutions.append(x)

